// Sync, second version: one encrypted copy in the cloud, like a backup.
// Run once from the repo root:  node sync2.mjs
// It checks that each file is still the version from your last commit before writing, so it never overwrites edits
// you made since. A file that differs is skipped and listed; run with --force to write it anyway.
import fs from "node:fs";
import crypto from "node:crypto";

const FILES = [{"path": "src/app/api/sync/image/route.ts", "old": "c436a11e327b2004ed4410219d22574082004e84761cb7fdaf3f7bce758f54be", "text": "import { getFile, IMAGE, MAX_PART_BYTES, problem, putFile, setup, SPACE, upstream } from \"../supabase\";\n\nexport const runtime = \"nodejs\";\nexport const dynamic = \"force-dynamic\";\nexport const maxDuration = 30;\n\n/**\n * PUT ?space&id saves one encrypted image. GET returns it. An image never changes (its id is a hash of the picture),\n * so each one is sent once and kept.\n */\n\nfunction target(req: Request): string | null {\n  const u = new URL(req.url);\n  const space = u.searchParams.get(\"space\") ?? \"\";\n  const id = u.searchParams.get(\"id\") ?? \"\";\n  return SPACE.test(space) && IMAGE.test(id) ? `${space}/img/${id}` : null;\n}\n\nexport async function PUT(req: Request) {\n  const path = target(req);\n  if (!path) return problem(400, \"The request was not valid.\");\n  const cfg = setup();\n  if (cfg instanceof Response) return cfg;\n  const bytes = new Uint8Array(await req.arrayBuffer());\n  if (bytes.length === 0 || bytes.length > MAX_PART_BYTES) return problem(413, \"The image is too big to sync.\");\n  try {\n    const res = await putFile(cfg, path, bytes);\n    if (!res.ok) return upstream(res);\n    return Response.json({ ok: true }, { headers: { \"Cache-Control\": \"no-store\" } });\n  } catch {\n    return problem(502, \"Could not reach the sync server.\");\n  }\n}\n\nexport async function GET(req: Request) {\n  const path = target(req);\n  if (!path) return problem(400, \"The request was not valid.\");\n  const cfg = setup();\n  if (cfg instanceof Response) return cfg;\n  try {\n    const res = await getFile(cfg, path);\n    if (!res.ok) return upstream(res);\n    return new Response(await res.arrayBuffer(), {\n      headers: { \"Content-Type\": \"application/octet-stream\", \"Cache-Control\": \"no-store\" },\n    });\n  } catch {\n    return problem(502, \"Could not reach the sync server.\");\n  }\n}\n"}, {"path": "src/app/api/sync/route.ts", "old": "65b37467b55b21c288c26168b31dbd26b1408b11ca7a240d341bf80759aa37a4", "text": "import {\n  headers,\n  MAX_PARTS,\n  noStore,\n  partPaths,\n  problem,\n  removeFiles,\n  setup,\n  SPACE,\n  UPLOAD,\n  upstream,\n} from \"./supabase\";\n\nexport const runtime = \"nodejs\";\nexport const dynamic = \"force-dynamic\";\nexport const maxDuration = 30;\n\n/**\n * POST { action: \"head\", space } says which version of the synced copy is in the cloud, and how it is stored.\n * POST { action: \"commit\", space, expected, upload, parts, size } makes an uploaded copy the current one, but only if\n * the cloud still has version `expected`. If another device saved first, it answers ok: false and this device merges\n * that copy and tries again, so no device ever overwrites another's work.\n */\n\ninterface Head {\n  version: number;\n  upload?: string;\n  parts?: number;\n  size?: number;\n}\n\nexport async function POST(req: Request) {\n  let body: Record<string, unknown>;\n  try {\n    body = (await req.json()) as Record<string, unknown>;\n  } catch {\n    return problem(400, \"The request was not valid.\");\n  }\n  const space = body.space;\n  if (typeof space !== \"string\" || !SPACE.test(space)) return problem(400, \"The sync code is not valid.\");\n  const cfg = setup();\n  if (cfg instanceof Response) return cfg;\n\n  try {\n    if (body.action === \"head\") {\n      const q = new URLSearchParams({ select: \"version,upload,parts,size\", space: `eq.${space}` });\n      const res = await fetch(`${cfg.url}/rest/v1/sync_snapshots?${q}`, {\n        headers: headers(cfg.key),\n        cache: \"no-store\",\n      });\n      if (!res.ok) return upstream(res);\n      const rows = (await res.json()) as Head[];\n      const h = rows[0];\n      return Response.json(\n        h\n          ? { version: Number(h.version), upload: h.upload, parts: Number(h.parts), size: Number(h.size) }\n          : { version: 0 },\n        noStore,\n      );\n    }\n\n    if (body.action === \"commit\") {\n      const { expected, upload, parts, size } = body;\n      if (\n        !Number.isSafeInteger(expected) ||\n        (expected as number) < 0 ||\n        typeof upload !== \"string\" ||\n        !UPLOAD.test(upload) ||\n        !Number.isSafeInteger(parts) ||\n        (parts as number) < 1 ||\n        (parts as number) > MAX_PARTS ||\n        !Number.isSafeInteger(size)\n      ) {\n        return problem(400, \"The request was not valid.\");\n      }\n      const res = await fetch(`${cfg.url}/rest/v1/rpc/sync_commit`, {\n        method: \"POST\",\n        headers: headers(cfg.key, { \"Content-Type\": \"application/json\" }),\n        body: JSON.stringify({ p_space: space, p_expected: expected, p_upload: upload, p_parts: parts, p_size: size }),\n        cache: \"no-store\",\n      });\n      if (!res.ok) return upstream(res);\n      const out = (await res.json()) as { ok: boolean; version: number; old_upload?: string; old_parts?: number };\n      // The copy that was replaced, or this upload if it lost the race, is no longer needed.\n      if (out.ok && out.old_upload) await removeFiles(cfg, partPaths(space, out.old_upload, Number(out.old_parts)));\n      if (!out.ok) await removeFiles(cfg, partPaths(space, upload, parts as number));\n      return Response.json({ ok: out.ok, version: Number(out.version) }, noStore);\n    }\n\n    return problem(400, \"Unknown sync action.\");\n  } catch (e) {\n    console.error(\"Sync route failed\", e);\n    return problem(502, \"Could not reach the sync server. Try again in a moment.\");\n  }\n}\n"}, {"path": "src/app/api/sync/supabase.ts", "old": "b115edce313c7d39424ad9074564c2658a1eb4d2eae0fbd85cf877f9f7865886", "text": "/**\n * The server side of sync: talks to Supabase with the secret key, which only exists here (in Vercel's environment\n * variables) and is never sent to a browser.\n *\n * Everything it stores was encrypted on the device with the sync code, which never reaches the server, so even with\n * the key nobody can read it.\n *\n * The synced copy is one file, like a backup, kept in a private bucket as numbered parts of at most 3.5 MB (the most\n * a Vercel function passes on is 4.5 MB). Images are separate files, one per picture, stored once.\n */\n\n/** The shared data's name: a 64-character hash of the sync code. */\nexport const SPACE = /^[0-9a-f]{64}$/;\n/** A name for one upload of the synced copy. */\nexport const UPLOAD = /^[0-9a-z]{16,40}$/;\n/** Image ids are SHA-256 hashes of the picture. */\nexport const IMAGE = /^[0-9a-f]{64}$/;\nexport const MAX_PARTS = 200;\nexport const MAX_PART_BYTES = 3_700_000;\n\nexport const BUCKET = \"sync-files\";\n\nexport class SetupError extends Error {}\n\nexport function config(): { url: string; key: string } {\n  const url = process.env.SUPABASE_URL?.trim().replace(/\\/+$/, \"\");\n  const key = process.env.SUPABASE_SECRET_KEY?.trim();\n  if (!url || !key) {\n    throw new SetupError(\n      \"Sync is not set up on the server yet. Add SUPABASE_URL and SUPABASE_SECRET_KEY to the site's environment variables, then redeploy.\",\n    );\n  }\n  return { url, key };\n}\n\n/** Headers for Supabase. A new secret key goes in apikey only; an older service_role key (a JWT) also as Bearer. */\nexport function headers(key: string, extra: Record<string, string> = {}): Record<string, string> {\n  return {\n    apikey: key,\n    ...(key.startsWith(\"eyJ\") ? { Authorization: `Bearer ${key}` } : {}),\n    ...extra,\n  };\n}\n\nexport function problem(status: number, error: string) {\n  return Response.json({ error }, { status, headers: { \"Cache-Control\": \"no-store\" } });\n}\n\nexport function setup(): { url: string; key: string } | Response {\n  try {\n    return config();\n  } catch (e) {\n    return problem(503, e instanceof SetupError ? e.message : \"Sync is not set up.\");\n  }\n}\n\n/** Turns a failed Supabase answer into a short message, without passing on anything secret. */\nexport async function upstream(res: Response): Promise<Response> {\n  const text = await res.text().catch(() => \"\");\n  console.error(\"Supabase error\", res.status, text.slice(0, 500));\n  if (res.status === 401 || res.status === 403) {\n    return problem(502, \"The sync server refused the key. Check SUPABASE_SECRET_KEY in the site's settings.\");\n  }\n  if (res.status === 404) {\n    return problem(502, \"The sync storage was not found. Run the setup SQL in Supabase.\");\n  }\n  return problem(502, `The sync server had a problem (${res.status}). Try again in a moment.`);\n}\n\n/** Stores one file in the bucket, replacing any file with that name. */\nexport async function putFile(\n  cfg: { url: string; key: string },\n  path: string,\n  bytes: Uint8Array<ArrayBuffer>,\n): Promise<Response> {\n  return fetch(`${cfg.url}/storage/v1/object/${BUCKET}/${path}`, {\n    method: \"POST\",\n    headers: headers(cfg.key, { \"Content-Type\": \"application/octet-stream\", \"x-upsert\": \"true\" }),\n    body: new Uint8Array(bytes),\n    cache: \"no-store\",\n  });\n}\n\nexport async function getFile(cfg: { url: string; key: string }, path: string): Promise<Response> {\n  return fetch(`${cfg.url}/storage/v1/object/${BUCKET}/${path}`, { headers: headers(cfg.key), cache: \"no-store\" });\n}\n\n/** Removes files. Used to clear out an older copy once a newer one is saved. */\nexport async function removeFiles(cfg: { url: string; key: string }, paths: string[]): Promise<void> {\n  if (!paths.length) return;\n  await fetch(`${cfg.url}/storage/v1/object/${BUCKET}`, {\n    method: \"DELETE\",\n    headers: headers(cfg.key, { \"Content-Type\": \"application/json\" }),\n    body: JSON.stringify({ prefixes: paths }),\n    cache: \"no-store\",\n  }).catch(() => undefined);\n}\n\nexport const partPaths = (space: string, upload: string, parts: number) =>\n  Array.from({ length: parts }, (_, i) => `${space}/copy/${upload}/${i}`);\n\nexport const noStore = { headers: { \"Cache-Control\": \"no-store\" } };\n"}, {"path": "src/components/help/HelpPage.tsx", "old": "002a37e4279c3221976018dcdc0b0c6295d2a1f59e1aaaf45255a51390a7267f", "text": "\"use client\";\n\nimport Link from \"next/link\";\nimport { CONFIG } from \"@/lib/config\";\nimport { formatPercent } from \"@/lib/format\";\nimport {\n  ChoicesDemo,\n  CreditTable,\n  MasteryStill,\n  MathPlayground,\n  PracticeResultStill,\n  QuestionStill,\n  QuizFormStill,\n  ReferenceLive,\n  ReferenceStill,\n  ResultsStill,\n  RollDemo,\n  TreeStill,\n  TrendLive,\n  TypedTable,\n} from \"./HelpFigures\";\n\nconst SECTIONS = [\n  { id: \"start\", label: \"Start here\" },\n  { id: \"bank\", label: \"The Bank\" },\n  { id: \"writing\", label: \"Writing questions\" },\n  { id: \"maths\", label: \"Maths and formatting\" },\n  { id: \"computation\", label: \"Dynamic questions\" },\n  { id: \"choices\", label: \"Choices and wrong answers\" },\n  { id: \"sources\", label: \"References and sources\" },\n  { id: \"concepts\", label: \"Concepts and AI drafts\" },\n  { id: \"quiz\", label: \"Taking a quiz\" },\n  { id: \"practice\", label: \"Practice quizzes\" },\n  { id: \"mock\", label: \"Mock boards\" },\n  { id: \"scoring\", label: \"Scoring and mastery\" },\n  { id: \"results\", label: \"Results and analytics\" },\n  { id: \"backup\", label: \"Backup and sharing\" },\n  { id: \"ai\", label: \"The AI helper\" },\n  { id: \"keys\", label: \"Keyboard and tips\" },\n  { id: \"trouble\", label: \"When something looks wrong\" },\n] as const;\n\nfunction Section({ id, title, children }: { id: string; title: string; children: React.ReactNode }) {\n  return (\n    <section id={id} aria-labelledby={`${id}-title`} className=\"scroll-mt-4 space-y-3\">\n      <h2 id={`${id}-title`} className=\"border-b border-line pb-1 text-lg font-semibold\">\n        {title}\n      </h2>\n      {children}\n    </section>\n  );\n}\n\nfunction Steps({ children }: { children: React.ReactNode }) {\n  return <ol className=\"list-decimal space-y-1.5 pl-6 text-sm\">{children}</ol>;\n}\n\nfunction Points({ children }: { children: React.ReactNode }) {\n  return <ul className=\"list-disc space-y-1.5 pl-6 text-sm\">{children}</ul>;\n}\n\nfunction P({ children }: { children: React.ReactNode }) {\n  return <p className=\"text-sm leading-relaxed\">{children}</p>;\n}\n\nfunction Btn({ children }: { children: React.ReactNode }) {\n  return (\n    <span className=\"rounded border border-line bg-surface px-1.5 py-0.5 text-[13px] font-medium\">{children}</span>\n  );\n}\n\nexport default function HelpPage() {\n  const q = CONFIG.quiz;\n  const d = CONFIG.masteryDays;\n  const contents = (\n    <ul className=\"space-y-0.5 text-sm\">\n      {SECTIONS.map((s) => (\n        <li key={s.id}>\n          <a href={`#${s.id}`} className=\"block rounded px-2 py-1 text-muted hover:bg-paper hover:text-ink\">\n            {s.label}\n          </a>\n        </li>\n      ))}\n    </ul>\n  );\n\n  return (\n    <div className=\"grid grid-cols-1 items-start gap-8 lg:grid-cols-[13rem_minmax(0,1fr)]\">\n      {/* On a computer the contents stay beside the text. On a phone they fold into a box at the top. */}\n      <nav aria-label=\"Contents\" className=\"card sticky top-4 p-3 max-lg:hidden\">\n        <p className=\"mb-2 text-sm font-medium\">Contents</p>\n        {contents}\n      </nav>\n      <details className=\"card p-3 lg:hidden\">\n        <summary className=\"cursor-pointer text-sm font-medium\">Contents</summary>\n        <nav aria-label=\"Contents\" className=\"mt-2\">\n          {contents}\n        </nav>\n      </details>\n\n      <div className=\"max-w-3xl space-y-10\">\n        <div>\n          <h1 className=\"text-xl font-semibold\">Help</h1>\n          <p className=\"mt-1 text-sm text-muted\">\n            What you can do here, and how. Pictures marked <span className=\"font-medium text-accent\">Live example</span>{\" \"}\n            are the real parts of the site, so you can try them. The other pictures show a screen, and cannot be\n            clicked.\n          </p>\n        </div>\n\n        <Section id=\"start\" title=\"Start here\">\n          <P>\n            ECE Review is your own question bank and a place to quiz yourself on it. Everything you write is kept in\n            this browser, on this computer. Nothing leaves it unless you turn on the AI helper or share a file yourself.\n          </P>\n          <Steps>\n            <li>\n              Open the <Btn>Bank</Btn> from the profile menu at the top right, and add a subject and a topic.\n            </li>\n            <li>\n              Add questions to the topic. Aim for {q.topic.minItems} or more per topic, so a quiz can award mastery.\n            </li>\n            <li>\n              Go to <Btn>Quiz</Btn>, pick the topic, and start. Your <Btn>Home</Btn> page shows what to quiz next.\n            </li>\n            <li>\n              Open <Btn>Settings</Btn> and export a backup now and then. Clearing your browser data erases the bank.\n            </li>\n          </Steps>\n          <P>\n            The profile menu at the top right holds <Btn>Analytics</Btn>, <Btn>Bank</Btn>, <Btn>Settings</Btn>, and this{\" \"}\n            <Btn>Help</Btn> page.\n          </P>\n          <P>\n            On a phone, the tabs at the bottom open <Btn>Home</Btn>, <Btn>Quiz</Btn>, <Btn>Progress</Btn>, and{\" \"}\n            <Btn>More</Btn>. You can take quizzes and see your progress there. Writing and organising questions (the\n            Bank, Extract, the editor, and blueprints) needs a computer. To have the same bank on both, turn on{\" \"}\n            <Btn>Sync</Btn> in Settings on your computer, then scan its QR code with your phone. After that a finished\n            quiz, an edit, or a setting on either one reaches the other by itself.\n          </P>\n        </Section>\n\n        <Section id=\"bank\" title=\"The Bank\">\n          <P>\n            The Bank is where everything you own lives. Questions and Concepts have a tab each. The tree on the left\n            decides where things are filed.\n          </P>\n          <TreeStill />\n          <Points>\n            <li>\n              Hover a row to see its buttons: <Btn>+</Btn> adds a subject or topic inside it, <Btn>✎</Btn> renames, the\n              arrows move it up or down, and <Btn>✕</Btn> deletes it. You are asked before anything is deleted.\n            </li>\n            <li>\n              A subject can sit in more than one category, when two categories cover it. It is marked{\" \"}\n              <span className=\"rounded bg-accent-soft px-1.5 py-0.5 text-[10px] font-medium text-accent\">shared</span>,\n              and its questions count in each.\n            </li>\n            <li>\n              Click a topic or subject to see only its questions. The list can be searched, and each question can be\n              edited or deleted.\n            </li>\n            <li>\n              The tag row has <Btn>Untagged</Btn>, which shows the questions that have no tag so they are easy to find.\n              Under a tag such as <code>solving</code>, the questions that have only that kind of tag come first.\n            </li>\n          </Points>\n        </Section>\n\n        <Section id=\"writing\" title=\"Writing questions\">\n          <P>\n            Choose <Btn>New question</Btn>. Pick the category, subject, and topic, write the question, write the\n            choices, and mark the correct one. Empty choice boxes are left out when you save, so you can use two to\n            eight choices.\n          </P>\n          <Points>\n            <li>\n              <strong>Tags</strong> are optional labels such as “series circuits”. They group questions inside a topic\n              and show up in your analytics. A topic quiz is built from them: most quizzes are spread evenly across the\n              tags, and some lean on one tag for up to about {Math.round(CONFIG.build.focusShare.max * 100)}% of the\n              questions, so you do not get used to one shape. The tags <code>concept</code> and <code>solving</code> say\n              what kind of question it is, so a quiz never builds around them.\n            </li>\n            <li>\n              <strong>Reference</strong> is optional. It says where the question came from. See{\" \"}\n              <a href=\"#sources\" className=\"underline\">\n                References and sources\n              </a>\n              .\n            </li>\n            <li>\n              <strong>Times it can appear in one quiz</strong> is 1 unless you change it, and can go up to{\" \"}\n              {CONFIG.maxRepeats}. Each appearance counts as its own question. Copies are spread apart in the quiz, and\n              a dynamic question gets different numbers every time. Mock boards always show a question once.\n            </li>\n            <li>\n              <strong>Allow AI to reword</strong> lets the AI helper write alternative wordings of the question. Nothing\n              it writes is shown until it passes a check.\n            </li>\n            <li>\n              <Btn>Save and add another</Btn> keeps the topic, the type, the tags, and the source, so a run of questions\n              from one book goes quickly.\n            </li>\n          </Points>\n        </Section>\n\n        <Section id=\"maths\" title=\"Maths and formatting\">\n          <P>\n            Every text box on the site understands formatting and maths. Click into any box and a toolbar floats above\n            it with buttons for bold, italic, lists, tables, links, fractions, powers, roots, integrals, and more. You\n            can use the buttons or just type.\n          </P>\n          <MathPlayground />\n          <TypedTable />\n          <Points>\n            <li>\n              <strong>Pictures</strong>: paste, drop, or choose an image in a box and it is saved in your bank. Click a\n              picture in a quiz to enlarge it.\n            </li>\n            <li>\n              <strong>Formatting</strong>: <code>**bold**</code>, <code>*italic*</code>, lists that start with{\" \"}\n              <code>-</code> or <code>1.</code>, tables, and a single line break stays a line break.\n            </li>\n            <li>\n              Words inside a formula go in quotes so they are not read as letters, as in{\" \"}\n              <code>V_(&quot;out&quot;)</code>.\n            </li>\n          </Points>\n        </Section>\n\n        <Section id=\"computation\" title=\"Dynamic questions\">\n          <P>\n            A dynamic question is a recipe. Instead of one fixed question, you describe how to make many, and every quiz\n            rolls fresh numbers. The formula stays the same while the numbers change, which is what you want for problem\n            solving. Choose <Btn>Dynamic</Btn> as the type of question. A <Btn>Standard</Btn> question never changes:\n            you type the question and the choices yourself, and it can still be a calculation problem because you type\n            the numbers.\n          </P>\n          <Steps>\n            <li>\n              <strong>Question wording</strong>: write the question with <code>{\"{R1}\"}</code> where a number should go.\n              Add several wordings and one is picked at random.\n            </li>\n            <li>\n              <strong>Given values</strong>: for each name, choose how it is rolled, such as a list of values or a range\n              with a step. Values can use SI suffixes such as 4.7k, 2.2u, or 10m.\n            </li>\n            <li>\n              <strong>Derived values</strong> (optional): values worked out from the givens, such as{\" \"}\n              <code>XL = 2*pi*f*L</code>.\n            </li>\n            <li>\n              <strong>Constraints</strong> (optional): conditions every roll must meet, such as <code>R1 != R2</code>. A\n              roll that fails is thrown away.\n            </li>\n            <li>\n              <strong>Choices</strong>: write each choice as a formula and mark the correct one, or switch to sentences.\n            </li>\n            <li>\n              <strong>How answers are shown</strong>: the unit, the significant figures, and the notation: engineering\n              (3.18 kΩ), scientific (3.18 × 10³ Ω), or plain (3180 Ω).\n            </li>\n          </Steps>\n          <RollDemo />\n          <P>\n            Press <Btn>Roll a preview</Btn> in the editor to test your own recipe. A recipe that cannot make a question,\n            or makes two choices that are almost the same number, is reported with the reason, and cannot be saved until\n            it works.\n          </P>\n        </Section>\n\n        <Section id=\"choices\" title=\"Choices and wrong answers\">\n          <Points>\n            <li>\n              <strong>Formulas or sentences.</strong> With formulas, each choice is worked out to a number, so wrong\n              choices are the answers that wrong methods give, such as forgetting to invert. With sentences, each choice\n              is text, and can use <code>{\"{name}\"}</code> for a rolled value.\n            </li>\n            <li>\n              <strong>One toolbar for the choices.</strong> Click a choice, then press a button on the shared toolbar.\n            </li>\n            <li>\n              <strong>Suggest wrong choices.</strong> Writing the question and the right answer is easy. Coming up with\n              convincing wrong ones is not. Write the question, mark and fill in the correct choice, leave some choices\n              empty, and press <Btn>Suggest wrong choices</Btn>. The AI fills the empty boxes with confusing, similar,\n              or wrong-method answers, which you can edit. For a dynamic question, it suggests formulas, and every one\n              is checked to be a real, different answer before you see it. It needs the AI helper (see below).\n            </li>\n          </Points>\n          <ChoicesDemo />\n        </Section>\n\n        <Section id=\"sources\" title=\"References and sources\">\n          <P>\n            A reference says where a question or a concept came from. It shows in the Bank and when you review a quiz,\n            and never during the quiz. Most references come from a few books, so you save each book once and reuse it.\n          </P>\n          <ReferenceStill />\n          <Steps>\n            <li>\n              In the Reference box, choose <Btn>+ New source…</Btn>. Fill in the kind, the title, and whatever else you\n              know: author, edition, year, publisher, or a web address. Press <Btn>Save source</Btn>.\n            </li>\n            <li>\n              On each question, pick the source from the dropdown, then type only the page number, such as{\" \"}\n              <code>143</code> or <code>143-145</code>. The page box takes numbers only.\n            </li>\n            <li>\n              <Btn>Manage sources</Btn> lets you edit or remove a source. Questions that already use it keep their text.\n            </li>\n            <li>\n              <Btn>Type it myself</Btn> is there for anything that is not worth saving. Web addresses in a reference\n              become links.\n            </li>\n          </Steps>\n          <ReferenceLive />\n        </Section>\n\n        <Section id=\"concepts\" title=\"Concepts and AI drafts\">\n          <P>\n            A concept is a short note you write about an idea, such as a definition or a derivation, filed under a\n            topic. Open the <Btn>Concepts</Btn> tab in the Bank and choose <Btn>New concept</Btn>.\n          </P>\n          <Points>\n            <li>\n              With an AI key set up, tick concepts and press <Btn>Draft with AI</Btn>. The AI writes questions from each\n              concept, a second model checks them, and they wait for you inside the concept. You accept, edit, or reject\n              each one. Nothing is added to your bank until you accept it.\n            </li>\n            <li>A question you accept inherits the concept&apos;s reference, so you type it once.</li>\n            <li>\n              Concepts that already have drafts are skipped, so the same ideas are not asked twice, unless you ask to\n              redo them.\n            </li>\n          </Points>\n        </Section>\n\n        <Section id=\"quiz\" title=\"Taking a quiz\">\n          <P>\n            Open <Btn>Quiz</Btn> and choose a topic, a subject, or a category. A topic or a subject opens the form\n            below. A category opens a mock board.\n          </P>\n          <QuizFormStill />\n          <Points>\n            <li>\n              A topic quiz has {q.topic.minItems} to {q.topic.maxItems} questions ({q.topic.defaultItems} to start) and\n              always {q.topic.totalMinutes} minutes. A subject quiz has {q.subject.maxItems} questions and always{\" \"}\n              {q.subject.totalMinutes} minutes. A category mock is at least {q.category.minItems} questions, and you\n              choose the time. The suggested time is {q.suggestedSecPerItem} seconds a question.\n            </li>\n            <li>\n              The time is a target only. The timer counts up, never stops the quiz, and never changes your score. It is\n              shown afterward as a statistic. It stops while the browser tab is hidden.\n            </li>\n            <li>\n              A quiz in progress waits on the Quiz page with <Btn>Resume</Btn>. You can discard it, and then none of it\n              is scored.\n            </li>\n          </Points>\n          <QuestionStill />\n        </Section>\n\n        <Section id=\"practice\" title=\"Practice quizzes\">\n          <P>\n            Beside <Btn>Start quiz</Btn> there is a <Btn>Practice</Btn> button, on topic, subject, and mock board forms.\n            A practice quiz is the same quiz with the same settings, but it is only for learning.\n          </P>\n          <QuizFormStill practice />\n          <Points>\n            <li>It never awards mastery, even if you reach the bar.</li>\n            <li>It never starts the {CONFIG.cooldownHours}-hour lock, even if you do badly.</li>\n            <li>You can practise while an item is locked, or while it is already mastered.</li>\n            <li>It is saved with your other results and counted in your analytics, with a Practice label.</li>\n          </Points>\n          <PracticeResultStill />\n        </Section>\n\n        <Section id=\"mock\" title=\"Mock boards\">\n          <P>\n            A mock board is a quiz for a whole category, built from a blueprint that says how much of the quiz comes\n            from each subject or topic. Open <Btn>Blueprint</Btn> beside a category on the Quiz page.\n          </P>\n          <Points>\n            <li>\n              Add the subjects or topics you want, and give each a percent.{\" \"}\n              <Btn>Spread evenly across this category’s subjects</Btn> shares it out. The questions are split to match,\n              with whole numbers that add up exactly.\n            </li>\n            <li>\n              A mock has no pause, you cannot go back, and every question must be answered to move on. It ends after the\n              last one.\n            </li>\n            <li>\n              A mock shows each question once, whatever its repeat setting. <Btn>Practice</Btn> works here too.\n            </li>\n          </Points>\n        </Section>\n\n        <Section id=\"scoring\" title=\"Scoring and mastery\">\n          <P>\n            A right answer earns credit, and how sure you said you were decides how much. A wrong answer earns nothing,\n            and a right answer you marked “Just guessed” earns nothing either, so guessing never pays.\n          </P>\n          <CreditTable />\n          <Points>\n            <li>\n              A quiz <strong>passes</strong> at an average credit of {formatPercent(CONFIG.passBar, 0)}, or the mastery\n              bar you set in Settings. Nothing else is asked of it, and it does not matter which tags or topics came up.\n            </li>\n            <li>\n              A passing quiz that is long enough earns <strong>mastery</strong>: {d.topic} days for a topic, {d.subject}{\" \"}\n              for a subject, {d.category} for a category. Passing again starts a fresh window.\n            </li>\n            <li>\n              A failed quiz that could have earned mastery <strong>locks</strong> that item for {CONFIG.cooldownHours}{\" \"}\n              hours. Mastery you already hold is not removed. A quiz that is too short to award mastery never locks\n              anything.\n            </li>\n            <li>\n              Mastery needs at least {q.topic.minItems} questions for a topic, and {q.subject.minItems} for a subject or\n              category.\n            </li>\n            <li>\n              <strong>Recheck</strong> is on every result. It judges that quiz again under the mastery bar and minimum\n              now, and dates the mastery to the day the quiz was taken, so the time it lasts does not move. It can give\n              mastery and it can take it away. It never locks anything.\n            </li>\n            <li>\n              When the mastery bar or the minimums change, the quizzes whose mastery could still be running are\n              rechecked for you, and a message says how many gained or lost mastery. Older quizzes are left alone,\n              because they cannot change what is mastered now.\n            </li>\n          </Points>\n          <MasteryStill />\n        </Section>\n\n        <Section id=\"results\" title=\"Results and analytics\">\n          <ResultsStill />\n          <Points>\n            <li>\n              The results list every question with your answer, the right one, how sure you were, the time taken, and\n              the reference. You can show only the ones you got wrong, or lost credit on.\n            </li>\n            <li>\n              <strong>Analytics</strong> (profile menu) has three tabs. <strong>Mastery</strong> shows every category,\n              subject, and topic with its status and when it runs out. A red <strong>!</strong> on a row means something\n              in it has expired, and an amber one means something runs out within 3 days. <strong>Analytics</strong>{\" \"}\n              shows credit over time, your weakest topics, and how well your sureness matched your answers.{\" \"}\n              <strong>Strengths &amp; weak spots</strong> has short lists for each category, for tags or for single\n              questions: weakest, always sure, misconceptions (sure but wrong), unprepared (not sure or just guessed),\n              fastest, slowest, and careless (fast but wrong).\n            </li>\n            <li>\n              <strong>Home</strong> shows what is next to quiz, how many topics are left, what expires soon, and your\n              latest results.\n            </li>\n          </Points>\n          <TrendLive />\n        </Section>\n\n        <Section id=\"backup\" title=\"Backup and sharing\">\n          <P>\n            <strong>Sync</strong> (at the top of Settings) keeps your devices the same: the bank, images, quizzes and\n            results, and your settings and theme. Turn it on on one device, then add the others by scanning its QR code\n            or typing its code. It works like a backup kept in the cloud: a sync downloads the newest copy if another\n            device saved one and merges it in, the same way a backup Merge does, then saves a new copy with this\n            device&apos;s changes. It runs by itself when you open the site, when you finish a quiz, a minute after\n            other changes, and when you leave the site; the cloud button in the header syncs at once. Pictures are sent\n            once each. Everything is encrypted on your device with the code before it is sent, so only devices that know\n            the code can read it. Your AI keys are not synced. The resets in the Danger zone only empty the device you do\n            them on, and turn sync off there first.\n          </P>\n          <P>\n            Open <Btn>Settings</Btn> and find <strong>Backup and sharing</strong>.\n          </P>\n          <Points>\n            <li>\n              <strong>Full backup</strong> saves everything to a file (<code>.ecebak</code>): questions, concepts,\n              results, mastery, and your sources. You can protect it with a password. Restore it on this or another\n              computer.\n            </li>\n            <li>\n              <strong>Bank pack</strong> (<code>.ecepack</code>) shares only the learning material with someone else. It\n              never includes your results, mastery, or settings. Share only material you have the right to share.\n            </li>\n            <li>\n              <strong>Import</strong> shows what a file would add or change before anything happens. Importing a pack\n              never touches your quiz history.\n            </li>\n            <li>\n              <strong>Storage</strong> shows how much room is used. The site asks the browser not to delete your data\n              when it runs low on space.\n            </li>\n          </Points>\n        </Section>\n\n        <Section id=\"ai\" title=\"The AI helper\">\n          <P>\n            The AI helper is optional. Without it, everything works exactly as written. With it, you get reworded\n            questions, drafts from concepts, and suggested wrong choices.\n          </P>\n          <Points>\n            <li>\n              In <Btn>Settings</Btn>, add a key for a provider. The page shows how to get a free key from Groq. You can\n              also use an in-browser model that needs no key, for dynamic questions.\n            </li>\n            <li>\n              By default, keys are forgotten when you close the tab. Turn on “Remember my keys on this device” to keep\n              them.\n            </li>\n            <li>\n              Everything the AI writes is checked before you see it, and a reworded question is never shown in a quiz\n              until it is approved. Numbers and answers are never changed without a check.\n            </li>\n          </Points>\n        </Section>\n\n        <Section id=\"keys\" title=\"Keyboard and tips\">\n          <Points>\n            <li>\n              <strong>In a quiz</strong>: <Btn>A</Btn> to <Btn>H</Btn> pick a choice, <Btn>S</Btn> Sure, <Btn>W</Btn>{\" \"}\n              Wise guess, <Btn>N</Btn> Not sure, <Btn>J</Btn> Just guessed, <Btn>Enter</Btn> confirm.\n            </li>\n            <li>\n              <strong>In a text box</strong>: Ctrl+B bold, Ctrl+I italic. Press Enter in a list to continue it, and Tab\n              to indent.\n            </li>\n            <li>The small ⓘ marks next to headings explain the details of that part of the page.</li>\n            <li>The sun and moon button at the top switches between light and dark.</li>\n          </Points>\n        </Section>\n\n        <Section id=\"trouble\" title=\"When something looks wrong\">\n          <Points>\n            <li>\n              <strong>Start quiz is greyed out.</strong> The item is locked after a failed quiz, or the number of\n              questions is not valid. <Btn>Practice</Btn> still works while it is locked.\n            </li>\n            <li>\n              <strong>“Practice only” on the form.</strong> The quiz is too short, or there are too few questions, to\n              award mastery. Add questions, or ask for more.\n            </li>\n            <li>\n              <strong>A dynamic recipe will not save.</strong> Read the list above <Btn>Roll a preview</Btn>. It names\n              the exact box that has a problem.\n            </li>\n            <li>\n              <strong>Maths shows as plain text.</strong> Check that the formula sits between dollar signs.\n            </li>\n            <li>\n              <strong>My questions are gone.</strong> They live in this browser. A different browser, a private window,\n              or cleared site data starts empty. Restore your latest backup from{\" \"}\n              <Link href=\"/settings#backup\" className=\"underline\">\n                Settings\n              </Link>\n              .\n            </li>\n          </Points>\n        </Section>\n      </div>\n    </div>\n  );\n}\n"}, {"path": "src/components/settings/SyncPanel.tsx", "old": "04655879845b267126d016b8d22fe4e4ddb61433316cb6b5905744a1265ae6ee", "text": "\"use client\";\n\nimport { useEffect, useMemo, useState } from \"react\";\nimport qrcode from \"qrcode-generator\";\nimport { parseCode } from \"@/lib/sync/crypto\";\nimport { joinSync, turnOffSync, turnOnSync } from \"@/lib/sync/autoSync\";\nimport { syncNow } from \"@/lib/sync/engine\";\nimport { loadConfig, useSyncStatus } from \"@/lib/sync/syncState\";\nimport { confirmAction } from \"@/lib/ui/dialog\";\nimport { useNow } from \"@/lib/hooks\";\nimport InfoTip from \"@/components/ui/InfoTip\";\n\n/** \"just now\", \"3 minutes ago\", \"2 hours ago\", or a date. */\nexport function ago(ms: number, nowMs: number): string {\n  const s = Math.max(0, Math.round((nowMs - ms) / 1000));\n  if (s < 45) return \"just now\";\n  const m = Math.round(s / 60);\n  if (m < 60) return `${m} minute${m === 1 ? \"\" : \"s\"} ago`;\n  const h = Math.round(m / 60);\n  if (h < 24) return `${h} hour${h === 1 ? \"\" : \"s\"} ago`;\n  return new Date(ms).toLocaleDateString(undefined, { month: \"short\", day: \"numeric\" });\n}\n\n/** A QR code as plain SVG squares, so it needs no image and no script from elsewhere. */\nfunction Qr({ text }: { text: string }) {\n  const cells = useMemo(() => {\n    const qr = qrcode(0, \"M\");\n    qr.addData(text);\n    qr.make();\n    const n = qr.getModuleCount();\n    const dark: string[] = [];\n    for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) if (qr.isDark(r, c)) dark.push(`M${c} ${r}h1v1h-1z`);\n    return { n, d: dark.join(\"\") };\n  }, [text]);\n  return (\n    <svg\n      viewBox={`-2 -2 ${cells.n + 4} ${cells.n + 4}`}\n      className=\"size-44 rounded-md bg-white p-1\"\n      role=\"img\"\n      aria-label=\"QR code that opens this site on another device and fills in the sync code\"\n      shapeRendering=\"crispEdges\"\n    >\n      <path d={cells.d} fill=\"#000\" />\n    </svg>\n  );\n}\n\n/** The code from a link such as /settings#join=XXXX-…, which the QR code opens. */\nfunction codeFromLink(): string | null {\n  if (typeof window === \"undefined\") return null;\n  const m = window.location.hash.match(/join=([0-9A-Za-z-]+)/);\n  return m ? parseCode(m[1]) : null;\n}\n\nexport default function SyncPanel() {\n  const status = useSyncStatus();\n  const nowMs = useNow();\n  const [mode, setMode] = useState<\"start\" | \"join\">(\"start\");\n  const [typed, setTyped] = useState(\"\");\n  const [showCode, setShowCode] = useState(false);\n  const [problem, setProblem] = useState<string | null>(null);\n  const [linkCode, setLinkCode] = useState<string | null>(null);\n\n  // Opened from another device's QR code: fill in the code and point at the Join button.\n  useEffect(() => {\n    const fromLink = codeFromLink();\n    if (!fromLink) return;\n    // Take the code out of the address bar, so it is not left in the history.\n    history.replaceState(null, \"\", window.location.pathname + window.location.search + \"#sync\");\n    // Not cleared on unmount: in development React runs this twice, and the second run no longer sees the code.\n    window.setTimeout(() => {\n      setLinkCode(fromLink);\n      document.getElementById(\"sync\")?.scrollIntoView();\n    }, 0);\n  }, []);\n\n  const code = status.on ? loadConfig()?.code : undefined;\n  const joinLink = code && typeof window !== \"undefined\" ? `${window.location.origin}/settings#join=${code}` : \"\";\n\n  async function start() {\n    setProblem(null);\n    await turnOnSync();\n    setShowCode(true);\n  }\n\n  async function join(text: string) {\n    const parsed = parseCode(text);\n    if (!parsed) {\n      setProblem(\"That is not a whole sync code. It has 32 letters and digits, in 8 groups of 4.\");\n      return;\n    }\n    setProblem(null);\n    setLinkCode(null);\n    await joinSync(parsed);\n  }\n\n  async function stop() {\n    if (\n      await confirmAction({\n        title: \"Turn off sync on this device?\",\n        message:\n          \"This device stops sending and receiving changes. Nothing is deleted, here or on your other devices. You can join again later with the same code.\",\n        confirmLabel: \"Turn off sync\",\n      })\n    ) {\n      turnOffSync();\n      setShowCode(false);\n    }\n  }\n\n  if (!status.on) {\n    return (\n      <div className=\"card space-y-4 p-5\">\n        <p className=\"text-sm\">\n          Keep your laptop and phone the same: the bank, your quizzes and results, and your settings. It works like a\n          backup kept in the cloud: each device downloads the latest copy and merges it in, then saves a new copy with\n          its own changes. Everything is encrypted on your device before it leaves, with a code only your devices know.\n        </p>\n\n        {linkCode ? (\n          <div className=\"space-y-3 rounded-lg bg-accent-soft p-4\">\n            <p className=\"text-sm font-medium\">Join the devices that showed you this code?</p>\n            <p className=\"font-mono text-sm break-all\">{linkCode}</p>\n            <p className=\"text-sm text-muted\">\n              What is on this device and what is on the others are combined. Nothing is deleted.\n            </p>\n            <div className=\"flex flex-wrap gap-2\">\n              <button className=\"btn btn-primary\" onClick={() => void join(linkCode)}>\n                Join and sync\n              </button>\n              <button className=\"btn\" onClick={() => setLinkCode(null)}>\n                Not now\n              </button>\n            </div>\n          </div>\n        ) : (\n          <>\n            <div\n              role=\"tablist\"\n              aria-label=\"How to start\"\n              className=\"inline-flex overflow-hidden rounded-md border border-line\"\n            >\n              {(\n                [\n                  [\"start\", \"This is my first device\"],\n                  [\"join\", \"I have a code\"],\n                ] as const\n              ).map(([m, label], i) => (\n                <button\n                  key={m}\n                  role=\"tab\"\n                  aria-selected={mode === m}\n                  className={`px-3 py-1.5 text-sm ${i > 0 ? \"border-l border-line\" : \"\"} ${\n                    mode === m ? \"bg-accent-soft font-medium text-accent\" : \"text-muted hover:bg-paper\"\n                  }`}\n                  onClick={() => setMode(m)}\n                >\n                  {label}\n                </button>\n              ))}\n            </div>\n\n            {mode === \"start\" ? (\n              <div className=\"space-y-2\">\n                <p className=\"text-sm text-muted\">\n                  Makes a new sync code and sends everything on this device. Then add your other devices with it.\n                </p>\n                <button className=\"btn btn-primary\" disabled={status.running} onClick={() => void start()}>\n                  Turn on sync\n                </button>\n              </div>\n            ) : (\n              <form\n                className=\"space-y-2\"\n                onSubmit={(e) => {\n                  e.preventDefault();\n                  void join(typed);\n                }}\n              >\n                <label htmlFor=\"sync-code\" className=\"block text-sm font-medium\">\n                  Sync code from your other device\n                </label>\n                <input\n                  id=\"sync-code\"\n                  className=\"input font-mono\"\n                  placeholder=\"XXXX-XXXX-XXXX-XXXX-XXXX-XXXX-XXXX-XXXX\"\n                  autoComplete=\"off\"\n                  autoCapitalize=\"characters\"\n                  spellCheck={false}\n                  value={typed}\n                  onChange={(e) => setTyped(e.target.value)}\n                />\n                <p className=\"text-sm text-muted\">\n                  Or scan the QR code it shows with this device&apos;s camera. What is here and what is there are\n                  combined; nothing is deleted.\n                </p>\n                <button className=\"btn btn-primary\" disabled={status.running || !typed.trim()}>\n                  Join and sync\n                </button>\n              </form>\n            )}\n          </>\n        )}\n        {problem && <p className=\"text-sm text-danger\">{problem}</p>}\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"card space-y-4 p-5\">\n      <div className=\"flex flex-wrap items-center gap-3\">\n        <span\n          aria-hidden=\"true\"\n          className={`size-2.5 rounded-full ${\n            status.running ? \"bg-accent motion-safe:animate-pulse\" : status.error ? \"bg-priority-solid\" : \"bg-good\"\n          }`}\n        />\n        <p className=\"min-w-0 flex-1 text-sm\" role=\"status\" aria-live=\"polite\">\n          {status.running\n            ? (status.step ?? \"Syncing…\")\n            : status.lastSyncAt\n              ? `Synced ${ago(status.lastSyncAt, nowMs)}.`\n              : \"Not synced yet.\"}\n        </p>\n        <button className=\"btn\" disabled={status.running} onClick={() => void syncNow()}>\n          Sync now\n        </button>\n      </div>\n      {status.running && (\n        <div className=\"space-y-2\">\n          <div className=\"h-1.5 overflow-hidden rounded-full bg-track\" aria-hidden=\"true\">\n            {status.progress === undefined ? (\n              <div className=\"h-full w-1/3 rounded-full bg-accent motion-safe:animate-pulse\" />\n            ) : (\n              <div\n                className=\"h-full rounded-full bg-accent transition-[width]\"\n                style={{ width: `${Math.max(4, status.progress * 100)}%` }}\n              />\n            )}\n          </div>\n          <p className=\"text-xs text-muted\">\n            You can keep using the site. If the page is closed or reloaded before it finishes, nothing is lost: the next\n            sync starts again, and images already sent or received are not repeated.\n          </p>\n        </div>\n      )}\n      {status.error && !status.running && <p className=\"text-sm text-priority\">{status.error}</p>}\n      {status.note && !status.running && <p className=\"text-sm text-muted\">{status.note}</p>}\n\n      <div className=\"space-y-3 border-t border-line pt-4\">\n        <div className=\"flex items-center gap-1\">\n          <h3 className=\"text-sm font-medium\">Add another device</h3>\n          <InfoTip>\n            Anyone with this code can read and change your synced data, so only show it to your own devices. On the new\n            device, scan the QR code with its camera, or open Settings › Sync, choose I have a code, and type it.\n          </InfoTip>\n        </div>\n        {showCode && code ? (\n          <div className=\"flex flex-wrap items-center gap-5\">\n            <Qr text={joinLink} />\n            <div className=\"min-w-0 space-y-2\">\n              <p className=\"text-sm text-muted\">Scan this with the other device&apos;s camera, or type the code:</p>\n              <p className=\"font-mono text-sm font-semibold break-all\">{code}</p>\n              <button className=\"btn\" onClick={() => setShowCode(false)}>\n                Hide the code\n              </button>\n            </div>\n          </div>\n        ) : (\n          <button className=\"btn\" onClick={() => setShowCode(true)}>\n            Show the code and QR\n          </button>\n        )}\n      </div>\n\n      <div className=\"border-t border-line pt-4\">\n        <button className=\"btn btn-danger\" onClick={() => void stop()}>\n          Turn off sync on this device\n        </button>\n      </div>\n    </div>\n  );\n}\n"}, {"path": "src/lib/backup/backup.ts", "old": "8cffd61ac2b60b772c350a21678cecc47d953f8398432f16c696fff62e02cd35", "text": "import {\n  BackupError,\n  encodeFile,\n  step,\n  type Container,\n  type ImageFile,\n  type Manifest,\n  type OnStep,\n} from \"./backupFormat\";\nimport {\n  db,\n  type Blueprint,\n  type Concept,\n  type DraftQuestion,\n  type Question,\n  type SettingRow,\n  type TreeNode,\n  type Variant,\n} from \"@/lib/db\";\nimport { now } from \"@/lib/ids\";\nimport {\n  planBackupMerge,\n  planPackImport,\n  type BackupMergePlan,\n  type PackData,\n  type PackOptions,\n  type PackPlan,\n  type Tables,\n} from \"./merge\";\nimport { selectPackContent } from \"./share\";\n\n/** Everything stored in this browser, deleted records included. Sync sends this too. */\nexport async function loadTables(): Promise<Tables> {\n  const [nodes, questions, blueprints, attempts, variants, settings, concepts, drafts] = await Promise.all([\n    db.nodes.toArray(),\n    db.questions.toArray(),\n    db.blueprints.toArray(),\n    db.attempts.toArray(),\n    db.variants.toArray(),\n    db.settings.toArray(),\n    db.concepts.toArray(),\n    db.drafts.toArray(),\n  ]);\n  return { nodes, questions, blueprints, attempts, variants, settings, concepts, drafts };\n}\n\nasync function imageFiles(only?: Set<string>): Promise<ImageFile[]> {\n  const rows = only\n    ? (await db.images.bulkGet(Array.from(only))).filter((r) => r !== undefined)\n    : await db.images.toArray();\n  const out: ImageFile[] = [];\n  for (const r of rows) {\n    out.push({\n      id: r.id,\n      mime: r.mime,\n      width: r.width,\n      height: r.height,\n      createdAt: r.createdAt,\n      bytes: new Uint8Array(await r.blob.arrayBuffer()),\n    });\n  }\n  return out;\n}\n\nfunction manifest(kind: \"backup\" | \"pack\", counts: Record<string, number>, name?: string): Manifest {\n  return { app: \"ece-review\", format: 1, kind, createdAt: now(), name, counts };\n}\n\n/** A full backup of this browser: the bank, images, attempts, blueprints. Needs a password. */\nexport async function buildFullBackup(\n  password: string,\n  onStep?: OnStep,\n): Promise<{ bytes: Uint8Array; counts: Record<string, number> }> {\n  await step(onStep, \"Reading your questions and quizzes…\");\n  const tables = await loadTables();\n  await step(onStep, \"Reading your images…\");\n  const images = await imageFiles();\n  const counts = {\n    questions: tables.questions.filter((q) => !q.deletedAt).length,\n    attempts: tables.attempts.length,\n    variants: tables.variants.filter((v) => v.status === \"approved\" && !v.deletedAt).length,\n    images: images.length,\n  };\n  const container: Container = { manifest: manifest(\"backup\", counts), data: { ...tables }, images };\n  return { bytes: await encodeFile(container, password, undefined, onStep), counts };\n}\n\nexport interface PackExport {\n  bytes: Uint8Array;\n  counts: Record<string, number>;\n  blueprintsSkipped: number;\n}\n\n/** A bank pack: learning material only. No attempts, mastery, cooldowns, or settings. */\nexport async function buildPack(\n  scopeId: string | null,\n  name: string,\n  password?: string,\n  includeVariants = false,\n  onStep?: OnStep,\n): Promise<PackExport> {\n  await step(onStep, \"Reading the questions…\");\n  const tables = await loadTables();\n  const sel = selectPackContent(\n    tables.nodes,\n    tables.questions,\n    tables.blueprints,\n    scopeId,\n    tables.variants,\n    includeVariants,\n    tables.concepts,\n  );\n  const images = await imageFiles(new Set(sel.imageIds));\n  const counts = {\n    questions: sel.questions.length,\n    concepts: sel.concepts.length,\n    images: images.length,\n    treeItems: sel.nodes.length,\n    variants: sel.variants.length,\n  };\n  const container: Container = {\n    manifest: manifest(\"pack\", counts, name),\n    data: {\n      nodes: sel.nodes,\n      questions: sel.questions,\n      blueprints: sel.blueprints,\n      variants: sel.variants,\n      concepts: sel.concepts,\n    },\n    images,\n  };\n  return {\n    bytes: await encodeFile(container, password || undefined, undefined, onStep),\n    counts,\n    blueprintsSkipped: sel.blueprintsSkipped,\n  };\n}\n\n// ---------------------------------------------------------------------------------------------\n// Reading a file\n// ---------------------------------------------------------------------------------------------\n\nfunction arr<T>(data: Record<string, unknown[]>, key: string): T[] {\n  const v = data[key];\n  if (v === undefined) return [];\n  if (!Array.isArray(v)) throw new BackupError(\"corrupt\", `The file's \"${key}\" data is damaged.`);\n  return v as T[];\n}\n\nconst isStr = (v: unknown) => typeof v === \"string\";\n\n/** Basic shape checks, so a hand-edited or damaged file cannot put broken records in the database. */\nfunction validateTables(t: Tables): void {\n  const bad = (what: string, i: number) => {\n    throw new BackupError(\"corrupt\", `The file has an invalid ${what} (number ${i + 1}).`);\n  };\n  t.nodes.forEach((n, i) => {\n    if (\n      !isStr(n.id) ||\n      ![\"category\", \"subject\", \"topic\"].includes(n.kind) ||\n      !isStr(n.name) ||\n      typeof n.updatedAt !== \"number\"\n    )\n      bad(\"tree item\", i);\n  });\n  t.questions.forEach((q, i) => {\n    if (\n      !isStr(q.id) ||\n      !isStr(q.topicId) ||\n      !isStr(q.stem) ||\n      !Array.isArray(q.choices) ||\n      !isStr(q.correctChoiceId) ||\n      !Array.isArray(q.tags) ||\n      typeof q.updatedAt !== \"number\"\n    )\n      bad(\"question\", i);\n  });\n  t.blueprints.forEach((b, i) => {\n    if (\n      !isStr(b.id) ||\n      !isStr(b.categoryId) ||\n      typeof b.totalItems !== \"number\" ||\n      !Array.isArray(b.entries) ||\n      typeof b.updatedAt !== \"number\"\n    )\n      bad(\"blueprint\", i);\n  });\n  t.attempts.forEach((a, i) => {\n    if (!isStr(a.id) || !isStr(a.scopeNodeId) || !Array.isArray(a.items) || typeof a.updatedAt !== \"number\")\n      bad(\"quiz attempt\", i);\n  });\n  t.variants.forEach((v, i) => {\n    if (\n      !isStr(v.id) ||\n      !isStr(v.questionId) ||\n      ![\"concept\", \"frame\"].includes(v.kind) ||\n      ![\"pending\", \"approved\", \"discarded\"].includes(v.status) ||\n      !isStr(v.stem) ||\n      !Array.isArray(v.choices) ||\n      typeof v.updatedAt !== \"number\"\n    )\n      bad(\"variant\", i);\n  });\n  t.settings.forEach((r, i) => {\n    if (!isStr(r.id) || typeof r.updatedAt !== \"number\") bad(\"setting\", i);\n  });\n  t.concepts.forEach((c, i) => {\n    if (\n      !isStr(c.id) ||\n      !isStr(c.topicId) ||\n      !isStr(c.title) ||\n      !isStr(c.body) ||\n      !Array.isArray(c.tags) ||\n      typeof c.updatedAt !== \"number\"\n    )\n      bad(\"concept\", i);\n  });\n  t.drafts.forEach((d, i) => {\n    if (\n      !isStr(d.id) ||\n      !isStr(d.conceptId) ||\n      !isStr(d.stem) ||\n      !Array.isArray(d.choices) ||\n      ![\"pending\", \"accepted\", \"discarded\"].includes(d.status) ||\n      typeof d.updatedAt !== \"number\"\n    )\n      bad(\"draft\", i);\n  });\n}\n\nexport function tablesFrom(c: Container): Tables {\n  const t: Tables = {\n    nodes: arr<TreeNode>(c.data, \"nodes\"),\n    questions: arr<Question>(c.data, \"questions\"),\n    blueprints: arr<Blueprint>(c.data, \"blueprints\"),\n    attempts: arr(c.data, \"attempts\"),\n    variants: arr<Variant>(c.data, \"variants\"),\n    settings: arr<SettingRow>(c.data, \"settings\"),\n    concepts: arr<Concept>(c.data, \"concepts\"),\n    drafts: arr<DraftQuestion>(c.data, \"drafts\"),\n  };\n  validateTables(t);\n  return t;\n}\n\nexport interface BackupPreview {\n  kind: \"backup\";\n  manifest: Manifest;\n  incoming: Tables;\n  /** Same as incoming.drafts, kept here for the replace path. */\n  drafts: DraftQuestion[];\n  images: ImageFile[];\n  plan: BackupMergePlan;\n  newImages: ImageFile[];\n}\n\nexport interface PackPreview {\n  kind: \"pack\";\n  manifest: Manifest;\n  incoming: PackData;\n  images: ImageFile[];\n  local: PackData;\n  /** Images in the pack that this browser does not have. */\n  newImages: ImageFile[];\n}\n\nexport type Preview = BackupPreview | PackPreview;\n\n/** Looks at an opened file and works out what importing it would do. Changes nothing. */\nexport async function previewContainer(c: Container, onStep?: OnStep): Promise<Preview> {\n  await step(onStep, \"Comparing it with what is in this browser…\");\n  const tables = tablesFrom(c);\n  const have = new Set((await db.images.toCollection().primaryKeys()) as string[]);\n  const newImages = c.images.filter((i) => !have.has(i.id));\n  if (c.manifest.kind === \"backup\") {\n    const local = await loadTables();\n    return {\n      kind: \"backup\",\n      manifest: c.manifest,\n      incoming: tables,\n      drafts: tables.drafts,\n      images: c.images,\n      plan: planBackupMerge(local, tables),\n      newImages,\n    };\n  }\n  const local = await loadTables();\n  return {\n    kind: \"pack\",\n    manifest: c.manifest,\n    incoming: {\n      nodes: tables.nodes,\n      questions: tables.questions,\n      blueprints: tables.blueprints,\n      variants: tables.variants,\n      concepts: tables.concepts,\n    },\n    images: c.images,\n    local: {\n      nodes: local.nodes,\n      questions: local.questions,\n      blueprints: local.blueprints,\n      variants: local.variants,\n      concepts: local.concepts,\n    },\n    newImages,\n  };\n}\n\nexport function planPack(p: PackPreview, options: PackOptions): PackPlan {\n  return planPackImport(p.local, p.incoming, options);\n}\n\n// ---------------------------------------------------------------------------------------------\n// Applying\n// ---------------------------------------------------------------------------------------------\n\nfunction toImageRow(i: ImageFile) {\n  return {\n    id: i.id,\n    blob: new Blob([new Uint8Array(i.bytes)], { type: i.mime }),\n    mime: i.mime,\n    width: i.width,\n    height: i.height,\n    createdAt: i.createdAt,\n  };\n}\n\nexport async function applyBackup(p: BackupPreview, mode: \"merge\" | \"replace\"): Promise<void> {\n  await db.transaction(\n    \"rw\",\n    [db.nodes, db.questions, db.blueprints, db.attempts, db.images, db.variants, db.settings, db.concepts, db.drafts],\n    async () => {\n      if (mode === \"replace\") {\n        await Promise.all([\n          db.nodes.clear(),\n          db.questions.clear(),\n          db.blueprints.clear(),\n          db.attempts.clear(),\n          db.images.clear(),\n          db.variants.clear(),\n          db.settings.clear(),\n          db.concepts.clear(),\n          db.drafts.clear(),\n        ]);\n        await db.concepts.bulkPut(p.incoming.concepts ?? []);\n        await db.drafts.bulkPut(p.drafts);\n        await db.nodes.bulkPut(p.incoming.nodes);\n        await db.questions.bulkPut(p.incoming.questions);\n        await db.blueprints.bulkPut(p.incoming.blueprints);\n        await db.attempts.bulkPut(p.incoming.attempts);\n        await db.variants.bulkPut(p.incoming.variants);\n        await db.settings.bulkPut(p.incoming.settings);\n        await db.images.bulkPut(p.images.map(toImageRow));\n        return;\n      }\n      await db.nodes.bulkPut(p.plan.puts.nodes);\n      await db.questions.bulkPut(p.plan.puts.questions);\n      await db.blueprints.bulkPut(p.plan.puts.blueprints);\n      await db.attempts.bulkPut(p.plan.puts.attempts);\n      await db.variants.bulkPut(p.plan.puts.variants);\n      await db.settings.bulkPut(p.plan.puts.settings);\n      await db.concepts.bulkPut(p.plan.puts.concepts);\n      await db.drafts.bulkPut(p.plan.puts.drafts);\n      await db.images.bulkPut(p.newImages.map(toImageRow));\n    },\n  );\n}\n\n/** Applies a pack. It writes only tree items, questions, blueprints, and images, never attempts. */\nexport async function applyPack(p: PackPreview, plan: PackPlan): Promise<void> {\n  await db.transaction(\"rw\", [db.nodes, db.questions, db.blueprints, db.variants, db.concepts, db.images], async () => {\n    await db.concepts.bulkPut(plan.puts.concepts);\n    await db.nodes.bulkPut(plan.puts.nodes);\n    await db.questions.bulkPut(plan.puts.questions);\n    await db.blueprints.bulkPut(plan.puts.blueprints);\n    await db.variants.bulkPut(plan.puts.variants);\n    await db.images.bulkPut(p.newImages.map(toImageRow));\n  });\n}\n\n/** Triggers a download of the bytes as a file. */\nexport function downloadBytes(bytes: Uint8Array, filename: string): void {\n  const url = URL.createObjectURL(new Blob([new Uint8Array(bytes)], { type: \"application/octet-stream\" }));\n  const a = document.createElement(\"a\");\n  a.href = url;\n  a.download = filename;\n  document.body.appendChild(a);\n  a.click();\n  a.remove();\n  window.setTimeout(() => URL.revokeObjectURL(url), 10_000);\n}\n\nexport const today = () => new Date().toISOString().slice(0, 10);"}, {"path": "src/lib/backup/backupFormat.ts", "old": "3ac4ea5275191ad3fcc90f5e6a192ed3ee38e0004f65e1befb62804b674c9baa", "text": "import { strFromU8, strToU8, unzip, unzipSync, zip, zipSync, type Unzipped, type Zippable } from \"fflate\";\n\n/**\n * File layout\n *   magic \"ECEBK1\" (6) | kind (1) | then, depending on kind:\n *   kind 1 (full backup, encrypted) and kind 3 (pack, encrypted):\n *       iterations (4, big endian) | salt (16) | iv (12) | AES-256-GCM ciphertext\n *       The whole header up to the iv is authenticated, so the kind cannot be changed without detection.\n *   kind 2 (pack, no password): the zip bytes directly.\n * The zip holds manifest.json, data.json, images.json, and one file per image under images/.\n */\n\nexport const MAGIC = \"ECEBK1\";\nexport const KDF_ITERATIONS = 600_000;\nconst MAX_ITERATIONS = 5_000_000;\n\nexport type FileKind = \"backup\" | \"pack\";\n\nconst KIND_BACKUP_ENC = 1;\nconst KIND_PACK_PLAIN = 2;\nconst KIND_PACK_ENC = 3;\n\nexport type BackupErrorCode = \"not_ours\" | \"password_needed\" | \"wrong_password\" | \"corrupt\" | \"insecure\" | \"bad_input\";\n\nexport class BackupError extends Error {\n  code: BackupErrorCode;\n  constructor(code: BackupErrorCode, message: string) {\n    super(message);\n    this.code = code;\n  }\n}\n\nexport interface ImageFile {\n  id: string;\n  mime: string;\n  width: number;\n  height: number;\n  createdAt: number;\n  bytes: Uint8Array;\n}\n\nexport interface Manifest {\n  app: \"ece-review\";\n  format: 1;\n  kind: FileKind;\n  createdAt: number;\n  name?: string;\n  counts: Record<string, number>;\n}\n\nexport interface Container {\n  manifest: Manifest;\n  data: Record<string, unknown[]>;\n  images: ImageFile[];\n}\n\n/** A copy backed by a plain ArrayBuffer, which the Web Crypto typings require. */\nfunction buf(u8: Uint8Array): Uint8Array<ArrayBuffer> {\n  return new Uint8Array(u8);\n}\n\n/**\n * Reports what a long job is doing, such as \"Encrypting…\", so the page can show it. Each step also gives the\n * browser a moment to draw that text before the work goes on.\n */\nexport type OnStep = (label: string) => void;\n\n/** Shows a step and lets the page draw it before the next piece of work starts. */\nexport async function step(onStep: OnStep | undefined, label: string): Promise<void> {\n  if (!onStep) return;\n  onStep(label);\n  await new Promise((r) => setTimeout(r, 0));\n}\n\nfunction zipFiles(c: Container): Zippable {\n  const files: Zippable = {\n    \"manifest.json\": strToU8(JSON.stringify(c.manifest)),\n    \"data.json\": strToU8(JSON.stringify(c.data)),\n    \"images.json\": strToU8(\n      JSON.stringify(\n        c.images.map(({ id, mime, width, height, createdAt }) => ({ id, mime, width, height, createdAt })),\n      ),\n    ),\n  };\n  for (const img of c.images) files[`images/${img.id}`] = [img.bytes, { level: 0 }];\n  return files;\n}\n\nexport function buildZip(c: Container): Uint8Array {\n  return zipSync(zipFiles(c));\n}\n\n/**\n * The same zip, compressed in a background worker so the page never freezes. Falls back to doing it here when the\n * browser cannot start a worker.\n */\nexport async function buildZipAsync(c: Container): Promise<Uint8Array> {\n  const files = zipFiles(c);\n  try {\n    return await new Promise<Uint8Array>((ok, fail) => zip(files, (err, out) => (err ? fail(err) : ok(out))));\n  } catch {\n    return zipSync(files);\n  }\n}\n\nasync function unzipAsync(bytes: Uint8Array): Promise<Unzipped> {\n  try {\n    return await new Promise<Unzipped>((ok, fail) => unzip(bytes, (err, out) => (err ? fail(err) : ok(out))));\n  } catch {\n    return unzipSync(bytes);\n  }\n}\n\n/** Opens a zip made by buildZip, in a background worker when the browser allows. */\nexport async function readZipAsync(bytes: Uint8Array): Promise<Container> {\n  let files: Unzipped;\n  try {\n    files = await unzipAsync(bytes);\n  } catch {\n    throw new BackupError(\"corrupt\", \"The file is damaged or is not a backup made by this app.\");\n  }\n  return containerFrom(files);\n}\n\nexport function readZip(bytes: Uint8Array): Container {\n  let files: Record<string, Uint8Array>;\n  try {\n    files = unzipSync(bytes);\n  } catch {\n    throw new BackupError(\"corrupt\", \"The file is damaged or is not a backup made by this app.\");\n  }\n  return containerFrom(files);\n}\n\nfunction containerFrom(files: Record<string, Uint8Array>): Container {\n  try {\n    const manifest = JSON.parse(strFromU8(files[\"manifest.json\"])) as Manifest;\n    const data = JSON.parse(strFromU8(files[\"data.json\"])) as Record<string, unknown[]>;\n    const meta = JSON.parse(strFromU8(files[\"images.json\"])) as Omit<ImageFile, \"bytes\">[];\n    if (manifest.app !== \"ece-review\" || manifest.format !== 1) {\n      throw new Error(\"wrong manifest\");\n    }\n    const images = meta.map((m) => {\n      const bytes = files[`images/${m.id}`];\n      if (!bytes) throw new Error(\"missing image \" + m.id);\n      return { ...m, bytes };\n    });\n    return { manifest, data, images };\n  } catch {\n    throw new BackupError(\"corrupt\", \"The file is damaged or is not a backup made by this app.\");\n  }\n}\n\nfunction subtle(): SubtleCrypto {\n  if (typeof crypto === \"undefined\" || !crypto.subtle) {\n    throw new BackupError(\n      \"insecure\",\n      \"Encryption is not available here. Open the app at localhost or over https and try again.\",\n    );\n  }\n  return crypto.subtle;\n}\n\nasync function deriveKey(password: string, salt: Uint8Array, iterations: number): Promise<CryptoKey> {\n  const s = subtle();\n  const base = await s.importKey(\"raw\", buf(strToU8(password)), \"PBKDF2\", false, [\"deriveKey\"]);\n  return s.deriveKey(\n    { name: \"PBKDF2\", salt: buf(salt), iterations, hash: \"SHA-256\" },\n    base,\n    { name: \"AES-GCM\", length: 256 },\n    false,\n    [\"encrypt\", \"decrypt\"],\n  );\n}\n\nconst HEADER_LEN = 6 + 1 + 4 + 16 + 12;\n\n/**\n * Turns a container into file bytes. A full backup always needs a password.\n * A pack is encrypted only when a password is given.\n */\nexport async function encodeFile(\n  c: Container,\n  password?: string,\n  iterations = KDF_ITERATIONS,\n  onStep?: OnStep,\n): Promise<Uint8Array> {\n  if (c.manifest.kind === \"backup\" && !password) throw new BackupError(\"bad_input\", \"A full backup needs a password.\");\n  await step(onStep, \"Compressing…\");\n  const zip = await buildZipAsync(c);\n  const magic = strToU8(MAGIC);\n\n  if (!password) {\n    if (c.manifest.kind === \"backup\") throw new BackupError(\"bad_input\", \"A full backup needs a password.\");\n    const out = new Uint8Array(7 + zip.length);\n    out.set(magic, 0);\n    out[6] = KIND_PACK_PLAIN;\n    out.set(zip, 7);\n    return out;\n  }\n\n  await step(onStep, \"Encrypting with your password…\");\n  const header = new Uint8Array(HEADER_LEN);\n  header.set(magic, 0);\n  header[6] = c.manifest.kind === \"backup\" ? KIND_BACKUP_ENC : KIND_PACK_ENC;\n  new DataView(header.buffer).setUint32(7, iterations, false);\n  const salt = crypto.getRandomValues(new Uint8Array(16));\n  const iv = crypto.getRandomValues(new Uint8Array(12));\n  header.set(salt, 11);\n  header.set(iv, 27);\n\n  const key = await deriveKey(password, salt, iterations);\n  const cipher = new Uint8Array(\n    await subtle().encrypt({ name: \"AES-GCM\", iv: buf(iv), additionalData: buf(header) }, key, buf(zip)),\n  );\n  const out = new Uint8Array(HEADER_LEN + cipher.length);\n  out.set(header, 0);\n  out.set(cipher, HEADER_LEN);\n  return out;\n}\n\nexport interface Peek {\n  kind: FileKind;\n  encrypted: boolean;\n}\n\n/** Reads only the first bytes, so the app can tell what a file is before asking for a password. */\nexport function peekFile(bytes: Uint8Array): Peek {\n  if (bytes.length < 7 || strFromU8(bytes.subarray(0, 6)) !== MAGIC) {\n    throw new BackupError(\"not_ours\", \"This is not a file made by this app.\");\n  }\n  switch (bytes[6]) {\n    case KIND_BACKUP_ENC:\n      return { kind: \"backup\", encrypted: true };\n    case KIND_PACK_PLAIN:\n      return { kind: \"pack\", encrypted: false };\n    case KIND_PACK_ENC:\n      return { kind: \"pack\", encrypted: true };\n    default:\n      throw new BackupError(\"not_ours\", \"This file comes from a newer version of the app.\");\n  }\n}\n\n/** Opens a file. Throws `password_needed` or `wrong_password` when the password is missing or wrong. */\nexport async function decodeFile(bytes: Uint8Array, password?: string, onStep?: OnStep): Promise<Container> {\n  const peek = peekFile(bytes);\n  let zip: Uint8Array;\n\n  if (!peek.encrypted) {\n    zip = bytes.subarray(7);\n  } else {\n    if (!password) throw new BackupError(\"password_needed\", \"This file needs a password.\");\n    if (bytes.length < HEADER_LEN + 16) throw new BackupError(\"corrupt\", \"The file is damaged.\");\n    const header = bytes.slice(0, HEADER_LEN);\n    const iterations = new DataView(header.buffer).getUint32(7, false);\n    if (iterations < 1 || iterations > MAX_ITERATIONS) throw new BackupError(\"corrupt\", \"The file is damaged.\");\n    const salt = header.slice(11, 27);\n    const iv = header.slice(27, 39);\n    await step(onStep, \"Checking the password and decrypting…\");\n    const key = await deriveKey(password, salt, iterations);\n    try {\n      zip = new Uint8Array(\n        await subtle().decrypt(\n          { name: \"AES-GCM\", iv: buf(iv), additionalData: buf(header) },\n          key,\n          buf(bytes.subarray(HEADER_LEN)),\n        ),\n      );\n    } catch {\n      throw new BackupError(\"wrong_password\", \"Wrong password, or the file has been changed or damaged.\");\n    }\n  }\n\n  await step(onStep, \"Unpacking…\");\n  let files: Unzipped;\n  try {\n    files = await unzipAsync(zip);\n  } catch {\n    throw new BackupError(\"corrupt\", \"The file is damaged or is not a backup made by this app.\");\n  }\n  const container = containerFrom(files);\n  if (container.manifest.kind !== peek.kind) {\n    throw new BackupError(\"corrupt\", \"The file's type does not match its contents.\");\n  }\n  return container;\n}"}, {"path": "src/lib/sync/autoSync.ts", "old": "36e56ba656c91d05834a01292aa9ff52ace0669a56372fb3a1f9dd880d78f326", "text": "import { db } from \"@/lib/db\";\nimport { newSyncCode } from \"./crypto\";\nimport { LOCAL_CHANGE_EVENT } from \"./devicePrefs\";\nimport { applyingRemote, syncNow } from \"./engine\";\nimport { hasUnsentChanges, loadConfig, noteChange, saveConfig, setStatus } from \"./syncState\";\n\n/**\n * When sync runs by itself.\n *\n * Checking the cloud for a newer copy is quick, so it happens when the site opens, when you come back to it, and every\n * few minutes. Saving a copy sends everything, so it waits until you pause: a minute after your last change, at once\n * when you finish a quiz, and when you leave the site or switch to another app.\n */\n\nconst AFTER_CHANGE_MS = 60_000;\nconst AFTER_QUIZ_MS = 2_000;\nconst EVERY_MS = 5 * 60_000;\nconst ON_RETURN_AFTER_MS = 60_000;\n\nlet started = false;\nlet timer: number | undefined;\nlet lastRun = 0;\n\nfunction run() {\n  window.clearTimeout(timer);\n  timer = undefined;\n  if (!loadConfig()) return;\n  lastRun = Date.now();\n  void syncNow();\n}\n\n/** Asks for a sync after a pause. Many changes in a row make one sync. */\nexport function syncSoon(delay = AFTER_CHANGE_MS): void {\n  if (!loadConfig()) return;\n  window.clearTimeout(timer);\n  timer = window.setTimeout(run, delay);\n}\n\nconst TABLES = [\"nodes\", \"questions\", \"blueprints\", \"attempts\", \"variants\", \"settings\", \"concepts\", \"drafts\", \"images\"];\n\n/** Starts the automatic syncing. Safe to call more than once. */\nexport function startAutoSync(): void {\n  if (started || typeof window === \"undefined\") return;\n  started = true;\n\n  const changed = () => {\n    if (applyingRemote || !loadConfig()) return;\n    noteChange();\n    syncSoon();\n  };\n  for (const t of TABLES) {\n    const table = db.table(t);\n    table.hook(\"creating\", changed);\n    table.hook(\"deleting\", changed);\n    table.hook(\"updating\", (mods) => {\n      changed();\n      // A finished quiz is worth sending at once.\n      if (t === \"attempts\" && (mods as { status?: string }).status === \"submitted\" && !applyingRemote && loadConfig()) {\n        syncSoon(AFTER_QUIZ_MS);\n      }\n    });\n  }\n  window.addEventListener(LOCAL_CHANGE_EVENT, changed);\n  window.addEventListener(\"online\", () => syncSoon(1_000));\n  document.addEventListener(\"visibilitychange\", () => {\n    if (!loadConfig()) return;\n    if (document.visibilityState === \"hidden\" && hasUnsentChanges()) run();\n    else if (document.visibilityState === \"visible\" && Date.now() - lastRun > ON_RETURN_AFTER_MS) syncSoon(500);\n  });\n  window.setInterval(() => {\n    if (document.visibilityState === \"visible\") run();\n  }, EVERY_MS);\n\n  // Left over from the first version of sync, which sent items one by one.\n  try {\n    for (const k of [\"ece:syncPushed\", \"ece:syncWaitingImages\"]) localStorage.removeItem(k);\n  } catch {\n    // ignore\n  }\n\n  if (loadConfig()) syncSoon(1_500);\n}\n\n/** Turns sync on with a brand-new code. Use on the first device: it saves the first copy to the cloud. */\nexport async function turnOnSync(): Promise<string> {\n  const code = newSyncCode();\n  saveConfig({ code, version: 0 });\n  await syncNow();\n  return code;\n}\n\n/**\n * Links this device to the others that use this code. It downloads their copy and merges it in, then saves a copy\n * with what this device adds, so what is here and what is there are combined.\n */\nexport async function joinSync(code: string): Promise<void> {\n  saveConfig({ code, version: 0 });\n  noteChange();\n  await syncNow();\n}\n\n/** Stops syncing on this device. Nothing is deleted, here or on the other devices. */\nexport function turnOffSync(): void {\n  saveConfig(null);\n  setStatus({ on: false, running: false, error: undefined, note: undefined, step: undefined, lastSyncAt: undefined });\n}\n"}, {"path": "src/lib/sync/engine.ts", "old": "e928eb3e24d2c3b946ab49d297a42f0b8d01105490f5d4a990cfc33cbcc57f45", "text": "import { db, type StoredImage, type TreeNode } from \"@/lib/db\";\nimport { FIXED_CATEGORIES } from \"@/lib/bank/categories\";\nimport { loadTables, tablesFrom } from \"@/lib/backup/backup\";\nimport { buildZipAsync, readZipAsync, type Container } from \"@/lib/backup/backupFormat\";\nimport { planBackupMerge } from \"@/lib/backup/merge\";\nimport { now } from \"@/lib/ids\";\nimport { keyOf, open, seal, spaceOf } from \"./crypto\";\nimport { applyPrefs, readPrefs, type DevicePrefs } from \"./devicePrefs\";\nimport {\n  loadChanges,\n  loadCloudImages,\n  loadConfig,\n  loadImageMeta,\n  saveChanges,\n  saveImageMeta,\n  saveCloudImages,\n  saveConfig,\n  setStatus,\n  type SyncConfig,\n} from \"./syncState\";\n\n/**\n * Sync works like a backup kept in the cloud.\n *\n * The cloud holds one copy of everything, encrypted on the device with the sync code, plus each image once as its\n * own file. A sync:\n * 1. Asks which version of the copy the cloud has. If it is newer than the one this device last saw, it downloads it\n *    and merges it in with the same rule as a backup Merge: the newer copy of each item wins.\n * 2. If anything changed on this device since it last saved, it sends any new images, then saves a fresh copy.\n *    The cloud only takes it if no other device saved in the meantime; if one did, this device merges that copy\n *    first and tries again. So no device ever overwrites another's work.\n *\n * A sync that is cut short (the tab closed, the page reloaded, the connection dropped) changes nothing in the cloud;\n * the next one simply runs again. Images already sent or received are kept, so those are not repeated.\n */\n\ninterface ImageMeta {\n  id: string;\n  mime: string;\n  width: number;\n  height: number;\n  createdAt: number;\n}\n\ninterface Head {\n  version: number;\n  upload?: string;\n  parts?: number;\n}\n\n/** Each part of the copy stays under the 4.5 MB a Vercel function passes on. */\nconst PART_BYTES = 3_500_000;\n/** The biggest image sync sends (after encryption it must still fit in one part). */\nconst MAX_IMAGE_BYTES = 3_500_000;\nconst IMAGES_AT_ONCE = 4;\nconst MAX_TRIES = 4;\n\nexport class SyncError extends Error {}\n\n/** True while a downloaded copy is being written in, so those writes are not counted as changes made here. */\nexport let applyingRemote = false;\n\nasync function api<T>(body: unknown): Promise<T> {\n  let res: Response;\n  try {\n    res = await fetch(\"/api/sync\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify(body),\n    });\n  } catch {\n    throw new SyncError(\"You seem to be offline. Sync will try again when you are back online.\");\n  }\n  const json = (await res.json().catch(() => ({}))) as T & { error?: string };\n  if (!res.ok) throw new SyncError(json.error ?? `The sync server answered ${res.status}.`);\n  return json;\n}\n\nasync function fetchBytes(url: string): Promise<Uint8Array> {\n  const res = await fetch(url).catch(() => null);\n  if (!res) throw new SyncError(\"You seem to be offline. Sync will try again when you are back online.\");\n  if (!res.ok) {\n    const json = (await res.json().catch(() => ({}))) as { error?: string };\n    throw new SyncError(json.error ?? `The sync server answered ${res.status}.`);\n  }\n  return new Uint8Array(await res.arrayBuffer());\n}\n\nasync function putBytes(url: string, bytes: Uint8Array): Promise<void> {\n  const res = await fetch(url, {\n    method: \"PUT\",\n    headers: { \"Content-Type\": \"application/octet-stream\" },\n    body: new Blob([new Uint8Array(bytes)]),\n  }).catch(() => null);\n  if (!res) throw new SyncError(\"You seem to be offline. Sync will try again when you are back online.\");\n  if (!res.ok) {\n    const json = (await res.json().catch(() => ({}))) as { error?: string };\n    throw new SyncError(json.error ?? `The sync server answered ${res.status}.`);\n  }\n}\n\nconst q = (o: Record<string, string | number>) =>\n  new URLSearchParams(Object.entries(o).map(([k, v]) => [k, String(v)])).toString();\n\n/** Runs `fn` on every item, a few at a time. */\nasync function inParallel<T>(items: T[], at: number, fn: (item: T) => Promise<void>): Promise<void> {\n  let next = 0;\n  await Promise.all(\n    Array.from({ length: Math.min(at, items.length) }, async () => {\n      while (next < items.length) await fn(items[next++]);\n    }),\n  );\n}\n\n// ---------------------------------------------------------------------------------------------\n// Downloading and merging\n// ---------------------------------------------------------------------------------------------\n\nasync function download(space: string, key: CryptoKey, h: Head): Promise<Container> {\n  const parts: Uint8Array[] = [];\n  for (let i = 0; i < (h.parts ?? 0); i++) {\n    setStatus({ step: \"Downloading the latest copy…\", progress: i / (h.parts ?? 1) });\n    parts.push(await fetchBytes(`/api/sync/part?${q({ space, upload: h.upload!, n: i })}`));\n  }\n  setStatus({ step: \"Opening it…\", progress: undefined });\n  const all = new Uint8Array(parts.reduce((s, p) => s + p.length, 0));\n  let at = 0;\n  for (const p of parts) {\n    all.set(p, at);\n    at += p.length;\n  }\n  let zip: Uint8Array;\n  try {\n    zip = await open(key, all);\n  } catch {\n    throw new SyncError(\"The cloud copy could not be opened with this sync code.\");\n  }\n  return readZipAsync(zip);\n}\n\n/**\n * The four fixed categories are made on every device, so two devices that each started on their own can end up with\n * two MATH categories after a merge. This keeps the one that holds things and removes the empty copies.\n */\nasync function tidyCategories(): Promise<void> {\n  const nodes = (await db.nodes.toArray()).filter((n) => !n.deletedAt);\n  const hasChildren = (id: string) => nodes.some((n) => n.parentId === id || n.parentIds?.includes(id));\n  const t = now();\n  for (const f of FIXED_CATEGORIES) {\n    const same = nodes.filter((n) => n.kind === \"category\" && n.name.trim().toLowerCase() === f.name.toLowerCase());\n    if (same.length < 2) continue;\n    const rank = (n: TreeNode) => (hasChildren(n.id) ? 2 : 0) + (n.id.startsWith(\"fixed-\") ? 0 : 1);\n    const keep = [...same].sort((a, b) => rank(b) - rank(a) || a.createdAt - b.createdAt)[0];\n    for (const n of same) {\n      if (n.id !== keep.id && !hasChildren(n.id)) await db.nodes.update(n.id, { deletedAt: t, updatedAt: t });\n    }\n  }\n}\n\n/** Merges a downloaded copy in. Returns the images it lists, which the cloud has. */\nasync function mergeIn(c: Container): Promise<ImageMeta[]> {\n  setStatus({ step: \"Merging it into this device…\", progress: undefined });\n  const incoming = tablesFrom(c);\n  const plan = planBackupMerge(await loadTables(), incoming);\n  const p = plan.puts;\n  const count = Object.values(p).reduce((s, list) => s + list.length, 0);\n  if (count) {\n    applyingRemote = true;\n    try {\n      await db.transaction(\n        \"rw\",\n        [db.nodes, db.questions, db.blueprints, db.attempts, db.variants, db.settings, db.concepts, db.drafts],\n        async () => {\n          await db.nodes.bulkPut(p.nodes);\n          await db.questions.bulkPut(p.questions);\n          await db.blueprints.bulkPut(p.blueprints);\n          await db.attempts.bulkPut(p.attempts);\n          await db.variants.bulkPut(p.variants);\n          await db.settings.bulkPut(p.settings);\n          await db.concepts.bulkPut(p.concepts);\n          await db.drafts.bulkPut(p.drafts);\n        },\n      );\n    } finally {\n      applyingRemote = false;\n    }\n    await tidyCategories();\n  }\n  const prefs = (c.data.prefs?.[0] ?? null) as DevicePrefs | null;\n  if (prefs && prefs.updatedAt > readPrefs().updatedAt) applyPrefs(prefs);\n  return (c.data.imageMeta ?? []) as ImageMeta[];\n}\n\n/** Fetches the images the cloud has that this device does not. Each is saved as it arrives. */\nasync function receiveImages(space: string, key: CryptoKey, metas: ImageMeta[], cloud: Set<string>): Promise<number> {\n  const have = new Set((await db.images.toCollection().primaryKeys()) as string[]);\n  const missing = metas.filter((m) => !have.has(m.id));\n  let done = 0;\n  let failed = 0;\n  await inParallel(missing, IMAGES_AT_ONCE, async (m) => {\n    try {\n      const bytes = await open(key, await fetchBytes(`/api/sync/image?${q({ space, id: m.id })}`));\n      applyingRemote = true;\n      try {\n        await db.images.put({ ...m, blob: new Blob([new Uint8Array(bytes)], { type: m.mime }) });\n      } finally {\n        applyingRemote = false;\n      }\n      cloud.add(m.id);\n    } catch {\n      failed++;\n    }\n    setStatus({ step: `Downloading images… ${++done} of ${missing.length}`, progress: done / missing.length });\n  });\n  saveCloudImages(cloud);\n  return failed;\n}\n\n// ---------------------------------------------------------------------------------------------\n// Saving a copy\n// ---------------------------------------------------------------------------------------------\n\n/** Sends the images the cloud does not have yet. Returns how many are too big to sync. */\nasync function sendImages(space: string, key: CryptoKey, cloud: Set<string>): Promise<number> {\n  const ids = ((await db.images.toCollection().primaryKeys()) as string[]).filter((id) => !cloud.has(id));\n  let done = 0;\n  let tooBig = 0;\n  await inParallel(ids, IMAGES_AT_ONCE, async (id) => {\n    const img = (await db.images.get(id)) as StoredImage | undefined;\n    if (img) {\n      const bytes = new Uint8Array(await img.blob.arrayBuffer());\n      if (bytes.length > MAX_IMAGE_BYTES) tooBig++;\n      else {\n        await putBytes(`/api/sync/image?${q({ space, id })}`, await seal(key, bytes));\n        cloud.add(id);\n        saveCloudImages(cloud);\n      }\n    }\n    setStatus({ step: `Uploading images… ${++done} of ${ids.length}`, progress: done / ids.length });\n  });\n  return tooBig;\n}\n\nfunction randomName(): string {\n  return Array.from(crypto.getRandomValues(new Uint8Array(12)), (b) => b.toString(16).padStart(2, \"0\")).join(\"\");\n}\n\n/** Builds a copy of everything here, sends it, and asks the cloud to make it current. */\nasync function saveCopy(\n  space: string,\n  key: CryptoKey,\n  expected: number,\n  cloud: Set<string>,\n  knownMeta: ImageMeta[],\n): Promise<{ ok: boolean; version: number }> {\n  setStatus({ step: \"Packing everything up…\", progress: undefined });\n  const tables = await loadTables();\n  // Every image the cloud has, described here so the other devices know to fetch it.\n  const metas = new Map(knownMeta.filter((m) => cloud.has(m.id)).map((m) => [m.id, m]));\n  await db.images.each((i) => {\n    if (cloud.has(i.id))\n      metas.set(i.id, { id: i.id, mime: i.mime, width: i.width, height: i.height, createdAt: i.createdAt });\n  });\n  const container: Container = {\n    manifest: { app: \"ece-review\", format: 1, kind: \"backup\", createdAt: now(), counts: {} },\n    data: { ...tables, prefs: [readPrefs()], imageMeta: [...metas.values()] },\n    images: [],\n  };\n  const sealed = await seal(key, await buildZipAsync(container));\n\n  const upload = randomName();\n  const parts = Math.max(1, Math.ceil(sealed.length / PART_BYTES));\n  for (let i = 0; i < parts; i++) {\n    setStatus({ step: \"Uploading…\", progress: i / parts });\n    await putBytes(\n      `/api/sync/part?${q({ space, upload, n: i })}`,\n      sealed.subarray(i * PART_BYTES, Math.min(sealed.length, (i + 1) * PART_BYTES)),\n    );\n  }\n  setStatus({ step: \"Finishing…\", progress: undefined });\n  return api<{ ok: boolean; version: number }>({\n    action: \"commit\",\n    space,\n    expected,\n    upload,\n    parts,\n    size: sealed.length,\n  });\n}\n\n// ---------------------------------------------------------------------------------------------\n\nlet running: Promise<void> | null = null;\n\n/** Runs one sync now. A sync that is already running is joined rather than started twice. */\nexport function syncNow(): Promise<void> {\n  if (running) return running;\n  running = (async () => {\n    const run = async () => {\n      let cfg = loadConfig();\n      if (!cfg) return;\n      setStatus({ on: true, running: true, error: undefined, step: \"Checking for changes…\", progress: undefined });\n      try {\n        const [space, key] = await Promise.all([spaceOf(cfg.code), keyOf(cfg.code)]);\n        const cloud = loadCloudImages();\n        let knownMeta = loadImageMeta<ImageMeta>();\n        let failedImages = 0;\n        let tooBig = 0;\n\n        for (let tries = 0; ; tries++) {\n          if (tries >= MAX_TRIES) throw new SyncError(\"Another device kept saving at the same time. Try again.\");\n          const h = await api<Head>({ action: \"head\", space });\n\n          if (h.version > 0 && h.version !== cfg.version) {\n            const copy = await download(space, key, h);\n            knownMeta = await mergeIn(copy);\n            saveImageMeta(knownMeta);\n            for (const m of knownMeta) cloud.add(m.id);\n            saveCloudImages(cloud);\n            cfg = { ...cfg, version: h.version };\n            if (loadConfig()?.code === cfg.code) saveConfig(cfg);\n          }\n          // Fetch any listed image this device does not have yet, including ones a cut-short sync missed.\n          failedImages = await receiveImages(space, key, knownMeta, cloud);\n\n          const changes = loadChanges();\n          if (h.version > 0 && changes.made <= changes.sent) break;\n\n          const madeBefore = changes.made;\n          tooBig = await sendImages(space, key, cloud);\n          const saved = await saveCopy(space, key, cfg.version, cloud, knownMeta);\n          if (saved.ok) {\n            cfg = { ...cfg, version: saved.version };\n            if (loadConfig()?.code === cfg.code) saveConfig(cfg);\n            saveChanges({ ...loadChanges(), sent: madeBefore });\n            break;\n          }\n          // Another device saved first: go round again, merge its copy, and save after it.\n        }\n\n        const done: SyncConfig = { ...cfg, lastSyncAt: now() };\n        if (loadConfig()?.code === cfg.code) saveConfig(done);\n        setStatus({\n          running: false,\n          step: undefined,\n          progress: undefined,\n          lastSyncAt: done.lastSyncAt,\n          error: failedImages\n            ? `${failedImages} image${failedImages === 1 ? \"\" : \"s\"} could not be downloaded. Sync will try again.`\n            : undefined,\n          note: tooBig\n            ? `${tooBig} image${tooBig === 1 ? \" is\" : \"s are\"} over 3.5 MB, so ${tooBig === 1 ? \"it stays\" : \"they stay\"} on this device only.`\n            : undefined,\n        });\n      } catch (e) {\n        setStatus({\n          running: false,\n          step: undefined,\n          progress: undefined,\n          error: e instanceof SyncError ? e.message : \"Sync did not finish. Nothing was lost; it will try again.\",\n        });\n      }\n    };\n    // Only one tab syncs at a time.\n    if (typeof navigator !== \"undefined\" && navigator.locks) await navigator.locks.request(\"ece-sync\", run);\n    else await run();\n  })().finally(() => {\n    running = null;\n  });\n  return running;\n}\n"}, {"path": "src/lib/sync/syncState.ts", "old": "01a7a803f480c5ef9e5ce4b61f983b9859a68d524e256b5e51c9bd78761f762a", "text": "import { useSyncExternalStore } from \"react\";\n\n/**\n * What sync remembers on this device. The code is the secret that links devices; the server only ever sees a hash\n * of it.\n */\nexport interface SyncConfig {\n  code: string;\n  /** The version of the cloud copy this device last merged in or saved. */\n  version: number;\n  lastSyncAt?: number;\n}\n\nconst CONFIG = \"ece:sync\";\nconst CHANGES = \"ece:syncChanges\";\nconst CLOUD_IMAGES = \"ece:syncCloudImages\";\nconst IMAGE_META = \"ece:syncImageMeta\";\n\nfunction get(key: string): string | null {\n  try {\n    return localStorage.getItem(key);\n  } catch {\n    return null;\n  }\n}\n\nfunction set(key: string, value: string | null): void {\n  try {\n    if (value === null) localStorage.removeItem(key);\n    else localStorage.setItem(key, value);\n  } catch {\n    // Storage is full or blocked. Sync still works; it may just send a little more next time.\n  }\n}\n\nexport function loadConfig(): SyncConfig | null {\n  try {\n    const c = JSON.parse(get(CONFIG) ?? \"null\") as SyncConfig | null;\n    return c && typeof c.code === \"string\" && typeof c.version === \"number\" ? c : null;\n  } catch {\n    return null;\n  }\n}\n\nexport function saveConfig(c: SyncConfig | null): void {\n  set(CONFIG, c ? JSON.stringify(c) : null);\n  if (!c) {\n    set(CHANGES, null);\n    set(CLOUD_IMAGES, null);\n    set(IMAGE_META, null);\n  }\n  notify();\n}\n\n/**\n * Counts changes made on this device. `made` goes up with every change; `sent` is what `made` was when the last copy\n * was saved to the cloud. More made than sent means there is something to send.\n */\nexport function loadChanges(): { made: number; sent: number } {\n  try {\n    const c = JSON.parse(get(CHANGES) ?? \"null\") as { made: number; sent: number } | null;\n    return c ?? { made: 0, sent: 0 };\n  } catch {\n    return { made: 0, sent: 0 };\n  }\n}\n\nexport function saveChanges(c: { made: number; sent: number }): void {\n  set(CHANGES, JSON.stringify(c));\n}\n\nexport function noteChange(): void {\n  const c = loadChanges();\n  saveChanges({ ...c, made: c.made + 1 });\n}\n\nexport const hasUnsentChanges = () => {\n  const c = loadChanges();\n  return c.made > c.sent;\n};\n\n/** The images the cloud already has, so each picture is sent only once, even if a sync is cut short. */\nexport function loadCloudImages(): Set<string> {\n  try {\n    return new Set(JSON.parse(get(CLOUD_IMAGES) ?? \"[]\") as string[]);\n  } catch {\n    return new Set();\n  }\n}\n\nexport function saveCloudImages(ids: Set<string>): void {\n  set(CLOUD_IMAGES, JSON.stringify([...ids]));\n}\n\n/** The images the last cloud copy listed, so any this device is still missing are fetched at the next sync. */\nexport function loadImageMeta<T>(): T[] {\n  try {\n    return JSON.parse(get(IMAGE_META) ?? \"[]\") as T[];\n  } catch {\n    return [];\n  }\n}\n\nexport function saveImageMeta<T>(list: T[]): void {\n  set(IMAGE_META, JSON.stringify(list));\n}\n\n// ---------------------------------------------------------------------------------------------\n// What the page shows\n// ---------------------------------------------------------------------------------------------\n\nexport interface SyncStatus {\n  on: boolean;\n  running: boolean;\n  /** What a running sync is doing, such as \"Uploading…\". */\n  step?: string;\n  /** How far the current step is, from 0 to 1, when that is known. */\n  progress?: number;\n  lastSyncAt?: number;\n  error?: string;\n  /** Something worth knowing that is not a problem, such as images too big to sync. */\n  note?: string;\n}\n\nlet status: SyncStatus = { on: false, running: false };\nlet fresh = false;\nconst listeners = new Set<() => void>();\n\nfunction notify() {\n  fresh = false;\n  for (const l of listeners) l();\n}\n\nexport function setStatus(patch: Partial<SyncStatus>): void {\n  status = { ...current(), ...patch };\n  fresh = true;\n  for (const l of listeners) l();\n}\n\nfunction current(): SyncStatus {\n  if (!fresh) {\n    const c = typeof window === \"undefined\" ? null : loadConfig();\n    status = { ...status, on: !!c, lastSyncAt: c?.lastSyncAt ?? status.lastSyncAt };\n    fresh = true;\n  }\n  return status;\n}\n\nconst OFF: SyncStatus = { on: false, running: false };\n\nexport function useSyncStatus(): SyncStatus {\n  return useSyncExternalStore(\n    (cb) => {\n      listeners.add(cb);\n      return () => listeners.delete(cb);\n    },\n    current,\n    () => OFF,\n  );\n}\n"}, {"path": "src/app/api/sync/part/route.ts", "old": null, "text": "import { getFile, MAX_PART_BYTES, MAX_PARTS, problem, putFile, setup, SPACE, UPLOAD, upstream } from \"../supabase\";\n\nexport const runtime = \"nodejs\";\nexport const dynamic = \"force-dynamic\";\nexport const maxDuration = 30;\n\n/** PUT ?space&upload&n saves one part of an uploaded copy. GET returns it. */\n\nfunction target(req: Request): string | null {\n  const u = new URL(req.url);\n  const space = u.searchParams.get(\"space\") ?? \"\";\n  const upload = u.searchParams.get(\"upload\") ?? \"\";\n  const n = Number(u.searchParams.get(\"n\"));\n  if (!SPACE.test(space) || !UPLOAD.test(upload) || !Number.isInteger(n) || n < 0 || n >= MAX_PARTS) return null;\n  return `${space}/copy/${upload}/${n}`;\n}\n\nexport async function PUT(req: Request) {\n  const path = target(req);\n  if (!path) return problem(400, \"The request was not valid.\");\n  const cfg = setup();\n  if (cfg instanceof Response) return cfg;\n  const bytes = new Uint8Array(await req.arrayBuffer());\n  if (bytes.length === 0 || bytes.length > MAX_PART_BYTES) return problem(413, \"That part is too big.\");\n  try {\n    const res = await putFile(cfg, path, bytes);\n    if (!res.ok) return upstream(res);\n    return Response.json({ ok: true }, { headers: { \"Cache-Control\": \"no-store\" } });\n  } catch {\n    return problem(502, \"Could not reach the sync server.\");\n  }\n}\n\nexport async function GET(req: Request) {\n  const path = target(req);\n  if (!path) return problem(400, \"The request was not valid.\");\n  const cfg = setup();\n  if (cfg instanceof Response) return cfg;\n  try {\n    const res = await getFile(cfg, path);\n    if (!res.ok) return upstream(res);\n    return new Response(await res.arrayBuffer(), {\n      headers: { \"Content-Type\": \"application/octet-stream\", \"Cache-Control\": \"no-store\" },\n    });\n  } catch {\n    return problem(502, \"Could not reach the sync server.\");\n  }\n}\n"}];

if (!fs.existsSync("package.json") || !fs.existsSync("src/lib/db.ts")) throw new Error("Run this from the repo root (the folder with package.json).");
const force = process.argv.includes("--force");
const sha = (t) => crypto.createHash("sha256").update(t, "utf8").digest("hex");
let wrote = 0;
const skipped = [];
for (const f of FILES) {
  const exists = fs.existsSync(f.path);
  const current = exists ? fs.readFileSync(f.path, "utf8").replace(/\r\n/g, "\n") : null;
  const same = f.old === null ? !exists : current !== null && sha(current) === f.old;
  const done = current !== null && current === f.text;
  if (done) continue;
  if (!same && !force) {
    skipped.push(f.path);
    continue;
  }
  fs.mkdirSync(f.path.split("/").slice(0, -1).join("/"), { recursive: true });
  fs.writeFileSync(f.path, f.text);
  wrote++;
}
console.log(`Wrote ${wrote} of ${FILES.length} files.`);
if (skipped.length) {
  console.log("Skipped, because they changed since this was made:");
  for (const p of skipped) console.log("  " + p);
  console.log("Run again with --force to overwrite them.");
}
